     3	import java.util.List;
     4	
     5	/** Estrutura comum: título, cabeçalho, linhas e total. Cada relatório só diz o que muda. */
     6	abstract class CsvReport<P> implements Report {
     7	    static final String INN = "Pousada Maré Alta";
     8	
     9	    record Table(List<String> header, List<List<String>> rows, List<String> total) {}
    10	
    11	    private final String name;
    12	    private final String paramName;
    13	
    14	    CsvReport(String name, String paramName) {
    15	        this.name = name;
    16	        this.paramName = paramName;
    17	    }
    18	
    19	    @Override public String name() { return name; }
    20	
    21	    @Override public String paramName() { return paramName; }
    22	
    23	    abstract P parse(String value);
    24	
    25	    abstract String label(P period);
    26	
    27	    abstract Table table(P period);
    28	
    29	    @Override
    30	    public String render(String periodValue) {
    31	        P period = parse(periodValue);
    32	        Table table = table(period);
    33	        StringBuilder csv = new StringBuilder();
    34	        line(csv, List.of(INN, name, label(period)));
    35	        line(csv, table.header());
    36	        table.rows().forEach(row -> line(csv, row));
    37	        line(csv, table.total());
    38	        return csv.toString();
    39	    }
    40	
    41	    private static void line(StringBuilder csv, List<String> fields) {
    42	        csv.append(String.join(",", fields)).append('\n');
    43	    }
    44	}
