     1	package br.com.marealta.reports;
     2	
     3	import br.com.marealta.ApiException;
     4	import br.com.marealta.Reservation;
     5	import br.com.marealta.ReservationService;
     6	
     7	import java.time.YearMonth;
     8	import java.util.Comparator;
     9	import java.util.List;
    10	
    11	/** Relatório de um mês, sobre as reservas que começam nele. */
    12	abstract class MonthReport extends CsvReport<YearMonth> {
    13	    private final ReservationService reservations;
    14	
    15	    MonthReport(String name, ReservationService reservations) {
    16	        super(name, "month");
    17	        this.reservations = reservations;
    18	    }
    19	
    20	    @Override
    21	    YearMonth parse(String value) {
    22	        if (value == null || !value.matches("\\d{4}-\\d{2}")) {
    23	            throw ApiException.invalid("month deve estar no formato yyyy-MM");
    24	        }
    25	        try {
    26	            return YearMonth.parse(value);
    27	        } catch (java.time.DateTimeException e) {
    28	            throw ApiException.invalid("month deve estar no formato yyyy-MM");
    29	        }
    30	    }
    31	
    32	    @Override
    33	    String label(YearMonth month) {
    34	        return month.toString();
    35	    }
    36	
    37	    /** Reservas que começam no mês, por data de entrada e depois por número. */
    38	    List<Reservation> startingIn(YearMonth month) {
    39	        return reservations.all().stream()
    40	                .filter(r -> YearMonth.from(r.checkIn()).equals(month))
    41	                .sorted(Comparator.comparing(Reservation::checkIn).thenComparingInt(Reservation::id))
    42	                .toList();
    43	    }
    44	
    45	    /** Reservas que deixaram dinheiro com a pousada (base do financeiro e dos planos). */
    46	    List<Reservation> retainingMoneyIn(YearMonth month) {
    47	        return startingIn(month).stream().filter(r -> r.retained().signum() > 0).toList();
    48	    }
    49	}
