     1	package br.com.marealta.reports;
     2	
     3	import br.com.marealta.ApiException;
     4	import br.com.marealta.Reservation;
     5	import br.com.marealta.ReservationService;
     6	import br.com.marealta.Room;
     7	
     8	import java.time.LocalDate;
     9	import java.time.format.DateTimeParseException;
    10	import java.util.Comparator;
    11	import java.util.List;
    12	
    13	public class OccupancyReport extends CsvReport<LocalDate> {
    14	    private final ReservationService reservations;
    15	
    16	    public OccupancyReport(ReservationService reservations) {
    17	        super("occupancy", "date");
    18	        this.reservations = reservations;
    19	    }
    20	
    21	    @Override
    22	    LocalDate parse(String value) {
    23	        try {
    24	            if (value != null) return LocalDate.parse(value);
    25	        } catch (DateTimeParseException ignored) {
    26	            // cai no erro abaixo
    27	        }
    28	        throw ApiException.invalid("date deve estar no formato yyyy-MM-dd");
    29	    }
    30	
    31	    @Override
    32	    String label(LocalDate date) {
    33	        return date.toString();
    34	    }
    35	
    36	    @Override
    37	    Table table(LocalDate night) {
    38	        List<Reservation> occupying = reservations.all().stream()
    39	                .filter(r -> r.status().isPaid())
    40	                .filter(r -> !night.isBefore(r.checkIn()) && night.isBefore(r.checkOut()))
    41	                .sorted(Comparator.comparingInt((Reservation r) -> r.room().number()))
    42	                .toList();
    43	        List<List<String>> rows = occupying.stream()
    44	                .map(r -> List.of(String.valueOf(r.room().number()), r.room().type().name(),
    45	                        String.valueOf(r.id()), r.checkIn().toString(), r.checkOut().toString()))
    46	                .toList();
    47	        long rooms = occupying.stream().map(Reservation::room).distinct().count();
    48	        return new Table(List.of("room", "type", "reservation", "check_in", "check_out"), rows,
    49	                List.of("total", rooms + "/" + Room.ALL.size()));
    50	    }
    51	}
