    10	
    11	/** Taxa de turismo da prefeitura: valor por hóspede por noite, definido na configuração. */
    12	public class TourismTaxReport extends MonthReport {
    13	    private final BigDecimal ratePerGuestNight;
    14	
    15	    public TourismTaxReport(ReservationService reservations, BigDecimal ratePerGuestNight) {
    16	        super("tourism-tax", reservations);
    17	        this.ratePerGuestNight = ratePerGuestNight;
    18	    }
    19	
    20	    private BigDecimal taxOf(Reservation r) {
    21	        return Money.round(ratePerGuestNight.multiply(BigDecimal.valueOf((long) r.guests() * r.nights())));
    22	    }
    23	
    24	    @Override
    25	    Table table(YearMonth month) {
    26	        List<Reservation> paid = startingIn(month).stream().filter(r -> r.status().isPaid()).toList();
    27	        List<List<String>> rows = paid.stream()
    28	                .map(r -> List.of(String.valueOf(r.id()), String.valueOf(r.room().number()),
    29	                        r.checkIn().toString(), r.checkOut().toString(),
    30	                        String.valueOf(r.guests()), String.valueOf(r.nights()), Money.csv(taxOf(r))))
    31	                .toList();
    32	        BigDecimal total = paid.stream().map(this::taxOf).reduce(Money.round(BigDecimal.ZERO), BigDecimal::add);
    33	        return new Table(List.of("reservation", "room", "check_in", "check_out", "guests", "nights", "tax"),
    34	                rows, List.of("total", Money.csv(total)));
    35	    }
    36	}

