    13	public class Main {
    14	    public static void main(String[] args) {
    15	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
    16	        // Valor por hóspede por noite; a prefeitura muda todo ano.
    17	        BigDecimal tourismTax = Money.of(System.getenv().getOrDefault("TOURISM_TAX_RATE", "4.50"));
    18	
    19	        Outbox outbox = new Outbox();
    20	        ReservationService reservations = new ReservationService(outbox);
