    19	    private final BigDecimal discount;
    20	    private final BigDecimal total;
    21	    private ReservationStatus status = ReservationStatus.PENDING;
    22	    private BigDecimal amountPaid = Money.round(BigDecimal.ZERO);
    23	    private BigDecimal refund;
    24	
    25	    public Reservation(int id, Room room, String guestName, String guestEmail, String guestCpf,
    26	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    27	        this.id = id;
    28	        this.room = room;
    29	        this.guestName = guestName;
    30	        this.guestEmail = guestEmail;
    31	        this.guestCpf = guestCpf;
    32	        this.checkIn = checkIn;
    33	        this.checkOut = checkOut;
    34	        this.guests = guests;
    35	        this.ratePlan = ratePlan;
    36	        this.nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    37	        BigDecimal sum = Money.round(BigDecimal.ZERO);
    38	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    39	            sum = sum.add(Season.priceOfNight(room, night));
    40	        }
    41	        this.subtotal = sum;
    42	        this.discount = ratePlan.discount(sum);
    43	        this.total = sum.subtract(discount);
    44	    }
