    45	                .json(Map.of("error", e.code(), "message", e.getMessage())));
    46	
    47	        app.get("/rooms", ctx -> ctx.json(reservations.rooms().stream().map(Api::roomJson).toList()));
    48	
    49	        app.post("/reservations", ctx -> ctx.status(201).json(reservationJson(create(ctx))));
    50	        app.get("/reservations/{id}", ctx -> ctx.json(reservationJson(reservations.find(id(ctx)))));
    51	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(reservationJson(reservations.confirm(id(ctx)))));
    52	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(reservationJson(reservations.cancel(id(ctx)))));
    53	        app.post("/reservations/{id}/check-in", ctx -> ctx.json(reservationJson(reservations.checkIn(id(ctx)))));
    54	        app.post("/reservations/{id}/check-out", ctx -> ctx.json(receiptJson(reservations.checkOut(id(ctx)))));
    55	        app.get("/reservations/{id}/document", ctx -> ctx.json(receiptJson(reservations.document(id(ctx)))));
    56	
    57	        app.get("/messages", ctx -> ctx.json(outbox.all().stream().map(Api::messageJson).toList()));
    58	
    59	        for (Report report : reports) {
    60	            app.get("/reports/" + report.name(), ctx -> ctx
    61	                    .contentType("text/csv; charset=utf-8")
    62	                    .result(report.render(ctx.queryParam(report.paramName()))));
