    24	        out.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    25	        out.append("Entrada: ").append(BR_DATE.format(checkIn))
    26	                .append(" | Saída: ").append(BR_DATE.format(checkOut))
    27	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
