    22	    public synchronized Reservation create(int roomNumber, String guestName, String guestEmail, String guestCpf,
    23	                                           LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    24	        if (!checkOut.isAfter(checkIn)) {
    25	            throw ApiException.invalid("A saída deve ser depois da entrada");
    26	        }
    27	        if (guests < 1) {
    28	            throw ApiException.invalid("É preciso pelo menos um hóspede");
    29	        }
    30	        Room room = Room.ALL.stream().filter(r -> r.number() == roomNumber).findFirst()
    31	                .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + roomNumber + " não existe"));
    32	        if (guests > room.capacity()) {
    33	            throw new ApiException(422, "CAPACITY_EXCEEDED",
    34	                    "O quarto " + roomNumber + " comporta até " + room.capacity() + " pessoas");
    35	        }
    36	        boolean taken = reservations.stream()
    37	                .filter(r -> r.status() != ReservationStatus.CANCELLED)
    38	                .filter(r -> r.room().equals(room))
    39	                .anyMatch(r -> r.overlaps(checkIn, checkOut));
    40	        if (taken) {
    41	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Quarto " + roomNumber + " já reservado nesse período");
    42	        }
    43	        Reservation reservation = new Reservation(reservations.size() + 1, room, guestName, guestEmail,
    44	                guestCpf, checkIn, checkOut, guests, ratePlan);
    45	        reservations.add(reservation);
    46	        return reservation;
    47	    }
